<?php
return [
"CREATE TABLE IF NOT EXISTS expense_submissions (id BIGINT AUTO_INCREMENT PRIMARY KEY,submitted_by INT NOT NULL,expense_date DATE NOT NULL,category_id INT NOT NULL,method ENUM('cash','momo','card','bank','other') NOT NULL,amount DECIMAL(12,2) NOT NULL,vendor VARCHAR(120) NOT NULL,reference_no VARCHAR(80) NOT NULL,description VARCHAR(255) NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',submitted_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),reviewed_by INT NULL,reviewed_at DATETIME(6) NULL,review_reason VARCHAR(500) NULL,expense_id INT NULL UNIQUE,FOREIGN KEY(submitted_by) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(category_id) REFERENCES expense_categories(id) ON DELETE RESTRICT,FOREIGN KEY(expense_id) REFERENCES expenses(id) ON DELETE RESTRICT,INDEX pending_queue(status,id),INDEX own_submissions(submitted_by,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS expense_operations (actor_id INT NOT NULL,operation_key CHAR(32) NOT NULL,fingerprint CHAR(64) NOT NULL,result_type ENUM('expense','submission') NOT NULL,result_id BIGINT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(actor_id,operation_key),FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB",
"CREATE TABLE IF NOT EXISTS expense_schema (version INT PRIMARY KEY) ENGINE=InnoDB",
"CREATE TRIGGER IF NOT EXISTS expense_no_update BEFORE UPDATE ON expenses FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Posted expenses are immutable; use a separately authorized correction workflow'",
"CREATE TRIGGER IF NOT EXISTS expense_no_delete BEFORE DELETE ON expenses FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Posted expense history cannot be deleted'",
"CREATE TRIGGER IF NOT EXISTS expense_submission_no_delete BEFORE DELETE ON expense_submissions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Expense submissions are retained'",
"CREATE TRIGGER IF NOT EXISTS expense_submission_transition BEFORE UPDATE ON expense_submissions FOR EACH ROW BEGIN IF OLD.status<>'pending' OR NOT(NEW.submitted_by<=>OLD.submitted_by) OR NOT(NEW.expense_date<=>OLD.expense_date) OR NOT(NEW.category_id<=>OLD.category_id) OR NOT(NEW.method<=>OLD.method) OR NOT(NEW.amount<=>OLD.amount) OR NOT(NEW.vendor<=>OLD.vendor) OR NOT(NEW.reference_no<=>OLD.reference_no) OR NOT(NEW.description<=>OLD.description) OR NOT(NEW.submitted_at<=>OLD.submitted_at) OR NEW.status NOT IN ('approved','rejected') OR NEW.reviewed_by IS NULL OR NEW.reviewed_by=OLD.submitted_by OR NEW.reviewed_at IS NULL OR NEW.review_reason IS NULL OR CHAR_LENGTH(TRIM(NEW.review_reason))<5 OR (NEW.status='approved' AND NEW.expense_id IS NULL) OR (NEW.status='rejected' AND NEW.expense_id IS NOT NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid expense submission transition'; END IF; END"
];